window.products.push({"id":1125703,"name":"VCNY Home Ezra Reversible Quilt Set Twin XL 4 Piece","category":"homeandappliances","retail price":49.52,"sale price":null,"image":"https://m.media-amazon.com/images/I/91cx+0Wy1mL._AC_SL1500_.jpg","description":"With striking layers of mixed patterns, the Ezra Reversible Orange Medallion Quilt Set is the perfect addition to any bohemian bedroom. The quilt features a multi-color paisley and medallion motif on one side which reverses to reveal a contrasting abstract pattern—two gorgeous styles for one great value. Made of super-soft microfiber, the set also includes matching shams (one sham in Twin XL) and two decorative pillows to complete the look.","images":["https://m.media-amazon.com/images/I/91cx+0Wy1mL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Overstock","source_asin":"B077NT989H","category_path":"Home & Kitchen"},"sku":"BM-1125703","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B077NT989H","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B077NT989H","price_pending":true,"merchant_ready":false});
